<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue'
import {examHref} from './navigation'
import {allowLeaving} from './taskGuard'
import {request} from './api'
import TeacherReview from './TeacherReview.vue'
import SubmissionDetail from './SubmissionDetail.vue'
type Side={id:string;exam_id?:string;assessment_id?:string;score:number|null;max_score:number|null;valid:boolean;complete:boolean;reason:string;question_ids?:string[];answer_version?:number;source_fingerprint?:string;ai_reference_state?:Record<string,string>;ai_reference?:Record<string,number|null>}
type Row={student_name:string;class_name:string;student_no:string;confirmation_method:string;link_id:string|null;anonymous_code:string;objective:Side|null;subjective:Side|null;total_score:number|null;total_max:number|null;complete:boolean;status:string}
const props=defineProps<{assignmentId:string;selectedExamId?:string;refreshKey?:string|number}>()
const exams=ref<{exam_id:string;assignment_id:string;title:string}[]>([]),exam=ref(''),rows=ref<Row[]>([]),busy=ref(false),error=ref(''),review=ref(''),detail=ref('')
const exportScope=ref('all'),exportSide=ref('all'),report=ref<{objective_summary:{count:number;excluded_count:number;mean:number|null;maximum:number|null;minimum:number|null;pass_rate:number|null;excellent_rate:number|null;score_rate:number|null;distribution:Record<string,number>};subjective_summary:{count:number;excluded_count:number;mean:number|null;maximum:number|null;minimum:number|null;pass_rate:number|null;excellent_rate:number|null;score_rate:number|null;distribution:Record<string,number>};ai_question_diagnostics:Record<string,{count:number;mean:number}>;scope:string;observed_rows:number;participant_count:number|null;complete_count:number;incomplete_count:number;mean:number|null;median:number|null;maximum:number|null;minimum:number|null;pass_rate:number|null;excellent_rate:number|null;distribution:Record<string,number>;objective_questions:Record<string,{count:number;answered_count:number;correct_rate:number;mean:number;score_rate:number|null}>;subjective_questions:Record<string,{count:number;mean:number}>;subjective_note:string}>(),pass=ref(.6),excellent=ref(.85)
const method=(r:Row)=>({automatic_blank_zero:'明确空白自动0分',teacher_total_confirmation:'教师总分终评',teacher_batch_adoption:'批量采纳共识',teacher_point_review:'历史逐点终评'} as Record<string,string>)[r.confirmation_method]||r.confirmation_method||'—'
async function showReport(){error.value='';try{report.value=await request('/objective/api/unified-scores/report?records=all&exam_id='+exam.value+'&pass_ratio='+pass.value+'&excellent_ratio='+excellent.value)}catch(e){error.value=(e as Error).message}}
function exportUrl(kind:string){return '/objective/api/unified-scores/export.'+kind+'?records=all&exam_id='+encodeURIComponent(exam.value)+'&scope='+exportScope.value+'&side='+exportSide.value+'&pass_ratio='+pass.value+'&excellent_ratio='+excellent.value}
const refreshNotice=ref('')
watch(()=>props.refreshKey,()=>{if(!review.value&&!detail.value)void load();else refreshNotice.value='成绩来源已变化，完成当前核对后请刷新结果。'})
let revision=0
function score(s:Side|null){return !s?'—':s.valid?`${s.score} / ${s.max_score}`:s.reason+(s.max_score!==null?`（评分范围满分 ${s.max_score}）`:'')}
async function load(){const n=++revision;rows.value=[];report.value=undefined;refreshNotice.value='';error.value='';review.value='';detail.value='';if(!exam.value)return;busy.value=true;try{const data=await request<{rows:Row[]}>('/objective/api/unified-scores?records=all&exam_id='+encodeURIComponent(exam.value));if(n===revision){rows.value=data.rows;await showReport()}}catch(e){if(n===revision)error.value=(e as Error).message}finally{if(n===revision)busy.value=false}}
onMounted(async()=>{const n=++revision;try{const data=await request<{exams:typeof exams.value}>('/objective/api/source-exams');if(n!==revision)return;exams.value=data.exams.filter(e=>e.assignment_id===props.assignmentId);if(props.selectedExamId){if(!exams.value.some(e=>e.exam_id===props.selectedExamId))throw new Error('所选考试不属于当前考试来源或无权访问');exam.value=props.selectedExamId;await load()}else if(exams.value.length===1){exam.value=exams.value[0]!.exam_id;await load()}}catch(e){if(n===revision)error.value=(e as Error).message}})
onUnmounted(()=>revision++)
</script>
<template><section aria-label="统一成绩"><h3>统一成绩</h3>
  <p>只读汇总原有成绩。缺失、待复核、部分评分及版本不同的记录显示“尚未完整确认”，不按零分计入。无需重复确认总分。同一考试来源的阅卷记录统一查看，版本异常不混算。</p>
  <label v-if="!selectedExamId">正式考试<select v-model="exam" @change="load" :disabled="busy"><option value="">请选择</option><option v-for="e in exams" :key="e.exam_id" :value="e.exam_id">{{e.title}} · {{e.exam_id}}</option></select></label>
  <button @click="load" :disabled="busy||!exam">刷新统一成绩</button><div v-if="exam" class="context-actions"><label>导出内容<select aria-label="导出内容" v-model="exportSide"><option value="all">主客观题与整卷</option><option value="objective">仅客观题</option><option value="subjective">仅主观题</option></select></label><label>导出范围<select aria-label="导出范围" v-model="exportScope"><option value="complete">仅完整有效成绩（按所选题型）</option><option value="all">全部可用结果（含异常与AI参考）</option></select></label><a :href="exportUrl('csv')">导出 CSV</a><a :href="exportUrl('xlsx')">导出 Excel</a><button @click="showReport">查看考试评价</button></div>
<details v-if="exam"><summary>评价阈值</summary><label>及格比例<input v-model.number="pass" type="number" min="0" max="1" step=".01"/></label><label>优秀比例<input v-model.number="excellent" type="number" min="0" max="1" step=".01"/></label></details>
  <p v-if="report" class="context-actions"><strong>客观题有效 {{report.objective_summary.count}} 份</strong><strong>主观题已确认 {{report.subjective_summary.count}} 份</strong><strong>已关联 {{rows.filter(r=>r.link_id).length}} 对</strong><strong>整卷完整 {{report.complete_count}} 份</strong><span>其余 {{report.incomplete_count}} 条结果仍可导出，下方可查看独立分析。</span></p>
  <p v-if="refreshNotice" role="status">{{refreshNotice}}</p><p v-if="busy" aria-live="polite">正在查询…</p><p v-if="error" role="alert">{{error}}</p>
  <div v-if="exam&&!busy&&!error&&!rows.length" class="empty-state"><h4>本考试尚无答卷</h4><p>上传后即可查看、分析和导出两侧成绩。分开上传的答卷可按需关联。</p><a :href="examHref('upload',{assignmentId:assignmentId,examId:exam})">上传本考试答卷</a></div>
  <p v-if="rows.length" class="mobile-table-hint">成绩表可左右滑动，查看两侧分数及详情。</p><div v-if="rows.length" class="table-wrap score-table unified-grades" tabindex="0" aria-label="统一成绩表格"><table><thead><tr><th>匿名答卷编号</th><th>班级 / 姓名 / 座号</th><th>客观题</th><th>主观题确认成绩</th><th>主观题AI参考（非正式）</th><th>整卷成绩</th><th>确认方式</th><th>状态</th><th>详情</th></tr></thead><tbody>
    <tr v-for="(r,i) in rows" :key="r.link_id||r.objective?.id||r.subjective?.id||i"><td><span>{{r.anonymous_code}}</span></td><td>{{r.class_name||'—'}} · {{r.student_name||'匿名'}} · {{r.student_no||'—'}}</td>
      <td>{{score(r.objective)}}<small v-if="r.objective?.answer_version"> · 快照版本 {{r.objective.answer_version}}</small></td>
      <td>{{score(r.subjective)}}<small v-if="r.subjective?.question_ids?.length"> · 题目 {{r.subjective.question_ids.join('、')}}</small></td>
      <td>A {{r.subjective?.ai_reference?.A??'—'}} · B {{r.subjective?.ai_reference?.B??'—'}}<small v-if="r.subjective?.ai_reference_state">{{Object.values(r.subjective.ai_reference_state).join(' · ')}}</small></td><td>{{r.complete?`${r.total_score} / ${r.total_max}`:'尚未完整确认'}}</td><td>{{method(r)}}</td><td><span class="status-tag" :class="r.complete?'success':'neutral'">{{r.status}}</span></td>
      <td><a v-if="r.objective?.assessment_id" :href="examHref('objective',{assignmentId:assignmentId,examId:r.objective.exam_id||exam,mode:'formal'})+'&assessment='+encodeURIComponent(r.objective.assessment_id)">客观题详情与复核</a>
        <button v-if="r.subjective" @click="allowLeaving()&&(detail=r.subjective.id,review='')">主观题详情</button>
        <button v-if="r.subjective" @click="allowLeaving()&&(review=r.subjective.id,detail='')">确认最终总分</button></td></tr>
  </tbody></table></div>
<section v-if="report" class="unified-report" aria-label="统一考试评价"><h4>成绩与分析概览</h4><p>客观题平均 {{report.objective_summary.mean??'—'}} 分 · 排除待复核或版本异常 {{report.objective_summary.excluded_count}} 份；主观题平均 {{report.subjective_summary.mean??'—'}} 分 · 待确认或非完整范围 {{report.subjective_summary.excluded_count}} 份。</p><p>客观题最高 {{report.objective_summary.maximum??'—'}} · 最低 {{report.objective_summary.minimum??'—'}} · 及格率 {{report.objective_summary.pass_rate===null?'—':(report.objective_summary.pass_rate*100).toFixed(1)+'%'}}；主观题确认分最高 {{report.subjective_summary.maximum??'—'}} · 最低 {{report.subjective_summary.minimum??'—'}} · 及格率 {{report.subjective_summary.pass_rate===null?'—':(report.subjective_summary.pass_rate*100).toFixed(1)+'%'}}。</p><details><summary>单侧分数分布（按满分比例）</summary><p v-for="(v,k) in report.objective_summary.distribution" :key="'o'+k">客观题 {{k}}：{{v}}份</p><p v-for="(v,k) in report.subjective_summary.distribution" :key="'s'+k">主观题 {{k}}：{{v}}份</p></details><p>{{report.scope}}</p><p>实际参考人数：{{report.participant_count??'尚有未关联或异常答卷，不能可靠确定'}} · 完整成绩 {{report.complete_count}} · 缺失或异常记录 {{report.incomplete_count}}</p><p>完整整卷平均分 {{report.mean??'—'}} · 中位数 {{report.median??'—'}} · 最高 {{report.maximum??'—'}} · 最低 {{report.minimum??'—'}}</p><p>及格率 {{report.pass_rate===null?'—':(report.pass_rate*100).toFixed(1)+'%'}} · 优秀率 {{report.excellent_rate===null?'—':(report.excellent_rate*100).toFixed(1)+'%'}}</p><div class="context-actions"><span v-for="(v,k) in report.distribution" :key="k">{{k}}：{{v}} 人</span></div><details open><summary>客观题逐题正确率（独立有效样本）</summary><div class="table-wrap"><table><thead><tr><th>题号</th><th>有效样本 / 作答人数</th><th>正确率</th><th>平均分</th><th>得分率</th></tr></thead><tbody><tr v-for="(v,k) in report.objective_questions" :key="k"><td>{{k}}</td><td>{{v.count}} / {{v.answered_count}}</td><td>{{(v.correct_rate*100).toFixed(1)}}%</td><td>{{v.mean.toFixed(2)}}</td><td>{{v.score_rate===null?'—':(v.score_rate*100).toFixed(1)+'%'}}</td></tr></tbody></table></div></details><h5>已确认主观题小题统计</h5><p>{{report.subjective_note}}</p><p v-for="(v,k) in report.subjective_questions" :key="k">{{k}}：平均 {{v.mean}} 分（{{v.count}}份有确认小题分）</p><details><summary>AI小题诊断（非教师确认成绩）</summary><p v-for="(v,k) in report.ai_question_diagnostics" :key="k">{{k}}：平均 {{v.mean}} 分（{{v.count}}份）</p></details></section>
  <SubmissionDetail v-if="detail" :id="detail" />
  <TeacherReview v-if="review" :id="review" :expected-exam-id="rows.find(r=>r.subjective?.id===review)?.subjective?.exam_id||exam" @saved="load" />
</section></template>
